/**
 * Demonstrates why Java is a practical backend language:
 * clear types, immutable input data, small domain methods, and predictable output.
 *
 * Practice task:
 * 1. Compile this file with: javac BackendServiceExample.java
 * 2. Run it with: java BackendServiceExample
 * 3. Change the input and observe how validation protects the service boundary.
 */
public final class BackendServiceExample {
    public static void main(String[] args) {
        RegistrationRequest request = new RegistrationRequest("java-labs@example.com", "Java Labs");
        AccountSummary summary = register(request);
        System.out.println(summary.displayName() + " <" + summary.email() + ">");
    }

    /**
     * Service-style method: validate input, normalize data, then return a stable result.
     */
    private static AccountSummary register(RegistrationRequest request) {
        requireText(request.email(), "email");
        requireText(request.displayName(), "displayName");

        String normalizedEmail = request.email().trim().toLowerCase();
        String cleanDisplayName = request.displayName().trim();
        return new AccountSummary(normalizedEmail, cleanDisplayName);
    }

    private static void requireText(String value, String fieldName) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(fieldName + " must not be blank");
        }
    }

    /** Immutable request object. Records are concise and useful for DTO-style data. */
    record RegistrationRequest(String email, String displayName) {}

    /** Immutable response object returned by the service boundary. */
    record AccountSummary(String email, String displayName) {}
}

/**
 * Small environment checker for understanding JDK/JRE/JVM concepts.
 *
 * It does not require external libraries. Run it with:
 *   javac JavaRuntimeInfo.java
 *   java JavaRuntimeInfo
 */
public final class JavaRuntimeInfo {
    public static void main(String[] args) {
        printProperty("Java version", "java.version");
        printProperty("JVM name", "java.vm.name");
        printProperty("JVM vendor", "java.vm.vendor");
        printProperty("Runtime name", "java.runtime.name");
        printProperty("Java home", "java.home");
    }

    /** Prints one runtime property in a consistent, readable format. */
    private static void printProperty(String label, String propertyName) {
        String value = System.getProperty(propertyName, "<unknown>");
        System.out.printf("%-14s : %s%n", label, value);
    }
}

/**
 * Compile and inspect this class to connect source code with bytecode.
 *
 * Commands:
 *   javac CompilationFlowDemo.java
 *   javap -c CompilationFlowDemo
 *   java CompilationFlowDemo
 */
public final class CompilationFlowDemo {
    public static void main(String[] args) {
        int total = sumInclusive(1, 5);
        System.out.println("Total = " + total);
    }

    /**
     * Returns the sum from start to end, including both boundaries.
     * Keeping this method small makes the bytecode easier to inspect.
     */
    private static int sumInclusive(int start, int end) {
        int total = 0;
        for (int current = start; current <= end; current++) {
            total += current;
        }
        return total;
    }
}

/**
 * Shows why Java is object-oriented but still keeps primitive values.
 */
import java.util.List;

public final class PrimitiveVsWrapperDemo {
    public static void main(String[] args) {
        int primitiveCount = 3;
        Integer wrapperCount = Integer.valueOf(primitiveCount);
        List<Integer> counts = List.of(wrapperCount, 10, 20);

        System.out.println("Primitive: " + primitiveCount);
        System.out.println("Wrapper list: " + counts);
    }
}

/**
 * Demonstrates platform-neutral path handling.
 * Avoid hard-coded separators such as "C:\\temp\\file.txt" or "/tmp/file.txt"
 * when the code should run across operating systems.
 */
import java.nio.file.Path;

public final class CrossPlatformPathDemo {
    public static void main(String[] args) {
        Path reportPath = Path.of("reports", "daily", "summary.txt");
        System.out.println(reportPath);
    }
}

/**
 * Java is statically typed: the compiler checks method signatures before runtime.
 * This small example models a backend calculation with explicit input and output types.
 */
public final class StaticTypingDemo {
    public static void main(String[] args) {
        Money subtotal = new Money(100_00, "USD");
        Money total = addTax(subtotal, 8.25);
        System.out.println(total.currency() + " " + total.cents());
    }

    /** Returns a new value instead of mutating the original input. */
    private static Money addTax(Money subtotal, double taxPercent) {
        long tax = Math.round(subtotal.cents() * taxPercent / 100.0);
        return new Money(subtotal.cents() + tax, subtotal.currency());
    }

    record Money(long cents, String currency) {}
}
